      { name: "eggs", quantity: 1, unit: "count", category: "dairy-eggs" },
      { name: "spinach", quantity: 100, unit: "g", category: "produce" },
    ] },
    { day: 2, slot: "breakfast", name: "Egg fried rice", servings: 1, prepMinutes: 10, leftoversFromDay: 0, ingredients: [
