cat > server/research/match.test.js <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { pickProduct, relevance, costFor } from "./match.js";
import { parseSearch } from "./tntParser.js";
import fixtures from "./fixtures/tnt-search.json" with { type: "json" };

const profile = (o = {}) => ({ allergies: [], avoid: [], diet: "none", ...o });
const pick = (name, q, quantities, prof = profile()) =>
  pickProduct({ name, searchTerm: q, quantities }, parseSearch(fixtures[q]).products, prof, q);

test("relevance ranks the real green onion above a fish ball and chives", () => {
  const r = pick("green onions", "green onions", [{ amount: 145, unit: "g" }]);
  assert.equal(r.chosen.name, "Green Onion (1bunch)");
  assert.equal(r.status, "uncertain"); // grams vs a bunch → check quantity
  assert.ok(r.chosen.flags.includes("check-quantity"));
  assert.ok(!r.alternatives.some((a) => a.name.includes("Dace Ball")));
});

test("variant suffixes and flavours don't win: ground pork and garlic", () => {
  assert.ok(relevance("garlic", "Garlic 3pcs").score > relevance("garlic", "Tan Tan Xiang Pop Pepper with Garlic (280g)").score);
  assert.equal(relevance("garlic", "Ilocos Garlic flavour Chichacorn (350g)").complete, false);
  const pork = pick("ground pork", "ground pork", [{ amount: 850, unit: "g" }]);
  assert.equal(pork.chosen.name, "Ground Pork - Regular (~2lb)");
  assert.equal(pork.chosen.cost, 5.98); // $2.99/lb × ~2lb
});

test("cheapest way to cover the quantity", () => {
  const eggs = pick("eggs", "large eggs", [{ amount: 18, unit: "count" }]);
  assert.equal(eggs.chosen.name, "Burnbrae Farms Omega 3 Large Eggs (18pcs)"); // $6.79 beats 2 × 12
  const tofu = pick("firm tofu", "firm tofu", [{ amount: 1000, unit: "g" }]);
  assert.equal(tofu.chosen.packages, 3);
  assert.equal(tofu.chosen.cost, 5.91);
  assert.equal(tofu.status, "matched");
});

test("per-lb pricing uses the pack weight", () => {
  const p = { name: "Baby Bok Choy Sum (~1.5lb)", price: 1.68, perLb: true, size: { amount: 680, unit: "g", approx: true } };
  const c = costFor(p, [{ amount: 750, unit: "g" }]);
  assert.equal(c.packages, 2);
  assert.equal(c.cost, 5.04);
  assert.ok(c.flags.includes("price-by-weight"));
});

test("allergen and diet products are excluded", () => {
  const garlic = pick("garlic", "garlic", [{ amount: 60, unit: "g" }], profile({ allergies: ["peanuts"] }));
  assert.ok(garlic.excluded.some((e) => e.name.includes("Peanuts")));
  assert.ok(![garlic.chosen, ...garlic.alternatives].some((p) => /peanut/i.test(p.name)));
  const pork = pick("ground pork", "ground pork", [{ amount: 500, unit: "g" }], profile({ diet: "vegetarian" }));
  assert.equal(pork.status, "not_found");
});

test("nothing relevant → not_found", () => {
  const r = pickProduct({ name: "saffron", searchTerm: "saffron", quantities: [{ amount: 1, unit: "g" }] },
    parseSearch(fixtures["green onions"]).products, profile(), "saffron");
  assert.equal(r.status, "not_found");
  assert.equal(r.chosen, null);
});
EOF
cat > server/research/research.test.js <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { researchList, fallbackQueries } from "./research.js";
import { searchUrl } from "./tntParser.js";
import fixtures from "./fixtures/tnt-search.json" with { type: "json" };

const profile = { budget: 30, allergies: [], avoid: [], diet: "none" };
const fakeFetch = (fail = new Set()) => {
  const calls = [];
  const fn = async (urls) => {
    calls.push(urls);
    return new Map(urls.map((u) => {
      const q = decodeURIComponent(new URL(u).searchParams.get("query"));
      if (fail.has(q)) return [u, { ok: false, error: "timeout" }];
      return [u, fixtures[q] ?? { ok: true, text: 'Search results"x"Sorry! We couldn\'t find any products.', links: [], images: [] }];
    }));
  };
  fn.calls = calls;
  return fn;
};

const toBuy = [
  { name: "boneless chicken thighs", searchTerm: "boneless chicken thighs", category: "meat-seafood", quantities: [{ amount: 800, unit: "g" }] },
  { name: "firm tofu", searchTerm: "firm tofu", category: "tofu-plant-protein", quantities: [{ amount: 454, unit: "g" }] },
  { name: "saffron", searchTerm: "saffron", category: "pantry", quantities: [{ amount: 1, unit: "g" }] },
];

test("fallback queries drop adjectives, then use the head noun", () => {
  assert.deepEqual(fallbackQueries("boneless chicken thighs"), ["chicken thighs", "thigh"]);
  assert.deepEqual(fallbackQueries("garlic"), []);
});

test("prices a list with a fallback search, totals, and budget warning", async () => {
  const fetchPages = fakeFetch();
  const r = await researchList(toBuy, profile, { fetchPages, now: () => new Date("2026-11-21T20:00:00Z") });
  const [chicken, tofu, saffron] = r.items;
  assert.equal(chicken.query, "chicken thighs"); // found on the second round
  assert.match(chicken.chosen.name, /Chicken Thigh Boneless/);
  assert.equal(tofu.chosen.cost, 1.97);
  assert.equal(saffron.status, "not_found");
  assert.equal(r.total, Math.round((chicken.chosen.cost + 1.97) * 100) / 100);
  assert.equal(r.overBudget, false);
  assert.ok(r.warnings.some((w) => w.type === "not-found"));
  assert.equal(r.retrievedAt, "2026-11-21T20:00:00.000Z");
  // round 1: all three; round 2: only the two misses
  assert.equal(fetchPages.calls[0].length, 3);
  assert.equal(fetchPages.calls[1].length, 2);
});

test("over budget and failed fetches are reported", async () => {
  const r = await researchList(toBuy.slice(0, 2), { ...profile, budget: 5 }, { fetchPages: fakeFetch(new Set(["firm tofu", "tofu"])) });
  assert.equal(r.overBudget, true);
  assert.equal(r.items[1].status, "not_found");
  assert.ok(r.warnings.some((w) => w.type === "budget"));
  assert.ok(r.warnings.some((w) => w.type === "fetch"));
});
