const slugWords = (url) =>
  new Set(url.replace(/^.*\/eng\/\d+-/, "").replace(/\.html$/, "").split("-").filter((w) => w.length > 1));
const nameWords = (name) =>
  name.toLowerCase().replace(/\([^)]*\)/g, " ").replace(/&/g, " ").split(/[^a-z0-9]+/).filter((w) => w.length > 1);

/**
 * Fallback when counts differ: give each product the unused link whose slug
 * shares the most words with its name (at least 60% of the slug's words, or
 * every word of a short slug). Products without a confident match keep url: null.
 */
function pairBySlug(products, urls) {
  const free = urls.map((u) => ({ u, w: slugWords(u) }));
  let all = true;
  for (const p of products) {
    const nw = new Set(nameWords(p.name));
    let best = null;
    for (const f of free) {
      const hits = [...f.w].filter((w) => nw.has(w) || nw.has(w + "s") || nw.has(w.replace(/s$/, ""))).length;
      const ratio = hits / Math.max(f.w.size, 1);
      if (hits >= 1 && ratio >= 0.6 && (!best || ratio > best.ratio)) best = { f, ratio };
    }
    if (best) {
      p.url = best.f.u;
      free.splice(free.indexOf(best.f), 1);
    } else {
      all = false;
    }
  }
  return all;
}

