/**
 * Fallback when counts differ: give each product the unused link whose slug
 * shares the most words with its name (at least 60% of the slug's words, or
 * every word of a short slug). Products without a confident match keep url: null.
 */
function pairBySlug(products, urls) {
  const free = urls.map((u) => ({ u, w: slugWords(u) }));
  let all = true;
  for (const p of products) {
    const nw = new Set(nameWords(p.name));
    let best = null;
